 dict(id='nice',title='NICE NG246 · Alimentación y actividad física',url='https://www.nice.org.uk/guidance/ng246/chapter/Physical-activity-and-diet',year=2025,kind='Guía clínica',reviewed='2026-10-04',limits='Contexto sanitario británico. No trasladamos sus tratamientos a una app de autocuidado.'),
