R=[]
def recipe(title,desc,minutes,servings,ingredients,steps,tags,allergens,swap):
 R.append(dict(id=f'recipe-{len(R)+1}',name=title,description=desc,minutes=minutes,servings=servings,ingredients=[dict(food='fdc-'+str(f),grams=g) for f,g in ingredients],steps=steps,tags=tags,allergens=allergens,substitution=swap,source='usda',reviewed='2026-10-04'))
recipe('Ensalada tibia de lentejas','Una base sencilla para aprovechar legumbres ya cocidas.',15,2,[(172421,300),(170457,200),(168409,100),(171413,10),(167746,20)],['Usá lentejas previamente cocidas y escurridas. Lavá el tomate, el pepino y el limón.','Cortá el tomate y el pepino. Entibiá las lentejas si lo preferís.','Mezclá con el aceite y la pulpa o jugo del limón. Repartí en dos porciones.'],['Económica','Vegetal'],[],'Podés usar porotos cocidos. La estimación corresponde solo a los ingredientes listados.')
recipe('Avena con banana y nueces','Un desayuno caliente, con ingredientes de todos los días.',12,1,[(169705,40),(173647,160),(173944,100),(170187,15)],['Cociná la avena en el agua siguiendo el tiempo de cocción del envase. Agregá agua si hace falta.','Cortá la banana sin cáscara.','Serví la avena con la banana y las nueces picadas.'],['Desayuno','Vegetal'],['Nueces','Avena: verificar gluten y contaminación cruzada'],'Cambiá la banana por pera. Revisá alergias antes de sustituir frutos secos.')
recipe('Tostada de palta y huevo','Para resolver una comida breve con una preparación conocida.',15,1,[(172688,80),(171705,70),(173424,50),(170457,80)],['Usá un huevo completamente cocido; pelalo y pesá la parte comestible.','Tostá el pan. Pisá la palta y lavá y cortá el tomate.','Armá las tostadas con palta, tomate y huevo.'],['Rápida'],['Trigo / gluten','Huevo'],'Podés servir los ingredientes con papa cocida en lugar de pan; los valores cambian.')
recipe('Bowl de quinoa y garbanzos','Colores y texturas para comer a tu ritmo.',15,2,[(168917,250),(173757,250),(170108,100),(168409,100),(171413,10),(167746,20)],['Partí de quinoa y garbanzos ya cocidos.','Lavá el morrón, el pepino y el limón. Cortá las verduras pequeñas.','Mezclá todo con aceite y limón y dividí en dos platos.'],['Vegetal','Para llevar'],[],'El arroz cocido puede reemplazar a la quinoa, con una composición diferente.')
recipe('Crema suave de calabaza','Una preparación cálida, sin pasos complicados.',15,2,[(168449,400),(170440,200),(173647,300),(171413,10)],['Usá calabaza y papa ya hervidas y escurridas, en los pesos indicados.','Calentalas con el agua hasta que estén bien calientes.','Pisá o procesá con cuidado. Añadí el aceite y ajustá la textura con agua.'],['Económica','Vegetal'],[],'Podés variar la proporción de papa y calabaza; la estimación dejará de ser la indicada.')
recipe('Yogur con frutillas y almendras','Una idea fresca para desayuno o colación.',5,1,[(171284,170),(167762,120),(170567,15)],['Lavá las frutillas y retirales las hojas.','Cortalas y mezclalas con el yogur.','Agregá las almendras picadas justo antes de servir.'],['Sin cocción','Rápida'],['Leche','Almendras'],'Usá una alternativa vegetal apropiada si la necesitás; su composición puede ser muy distinta.')
recipe('Arroz integral con pollo y brócoli','Una forma de combinar preparaciones que ya tenés listas.',12,2,[(169704,300),(171477,200),(169967,250),(171413,10)],['Usá arroz cocido, pollo completamente asado y brócoli hervido; los pesos son después de cocinar.','Cortá el pollo. Calentá los tres ingredientes de forma uniforme y completa.','Añadí el aceite y repartí. Usá preparaciones conservadas adecuadamente en frío.'],['Comida principal'],[],'Podés reemplazar el pollo por tofu; comprobá soja y otras alergias. Los valores cambiarán.')
recipe('Ensalada de papa y atún','Una combinación práctica sin cocinar desde cero.',12,2,[(170440,300),(171986,180),(170457,150),(171413,10),(167746,20)],['Partí de papa ya hervida y atún en agua escurrido.','Lavá y cortá el tomate y el limón.','Mezclá la papa en cubos con el atún, tomate, aceite y limón. Serví o refrigerá pronto.'],['Rápida','Comida principal'],['Pescado'],'Garbanzos cocidos pueden reemplazar al atún; recalculá si necesitás los valores.')
recipe('Boniato con porotos negros','Dos preparaciones simples que se encuentran en el plato.',12,2,[(168484,300),(173735,300),(170457,150),(171413,10)],['Usá boniato hervido sin piel y porotos ya cocidos.','Lavá y cortá el tomate.','Calentá boniato y porotos. Serví con tomate y aceite.'],['Vegetal','Económica'],[],'Lentejas cocidas son otra opción, con valores nutricionales diferentes.')
recipe('Ensalada de cebada y arvejas','Una idea para variar los cereales de la semana.',12,2,[(170285,300),(170420,200),(170108,100),(171413,10),(167746,20)],['Usá cebada y arvejas previamente cocidas.','Lavá el morrón y el limón; cortá el morrón.','Mezclá con el aceite y el limón. Serví tibia o enfriá y refrigerá pronto.'],['Vegetal','Para llevar'],['Cebada / gluten'],'La quinoa cocida permite otra variante; las estimaciones corresponden a la cebada.')
